            if (text.length > CONFIG.inventory.max2014SidecarBytes) { return { ok: false, error: I18N.t('blueprint.tooLarge') }; }
            var envelope = Utils.safeJsonParse(text.slice(SIDECAR_PREFIX_2014.length), null);
