            var modifier = String(fields && fields[key + 'mod'] || '').trim();
            var magicModifier = key === 'dmg' ? String(fields && fields.atkmagic || '').trim() : '';
            var combinedBonus = combinedPortableBonus(modifier, magicModifier);
