            target.parentID = '@row:' + attackAlias;
            target.sourceID = target.sourceID || '@row:i';
            target.ability = legacyNode.ability;
            target.damageType = legacyNode.damageType;
            target.diceSize = legacyNode.diceSize;
            target._diceCount = legacyNode._diceCount;
            target.overrideCrit = legacyNode.overrideCrit;
            target.critDiceSize = legacyNode.critDiceSize;
            target._tnt2014 = legacyNode._tnt2014;
            if (Object.prototype.hasOwnProperty.call(legacyNode, 'bonus')) { target.bonus = legacyNode.bonus; }
            else { delete target.bonus; }
            return target;
