            ep: Object.freeze({ id: 'electrum', name: 'Electrum', conversion: Object.freeze({ amountOfTarget: 5, target: 'silver' }) }),
            gp: Object.freeze({ id: 'gold', name: 'Gold', conversion: Object.freeze({ amountOfTarget: 10, target: 'silver' }) }),
