        function tokenBarComputedEntry2024(attributeName) {
            var requested = String(attributeName || '').trim();
            var wanted = requested.toLowerCase();
            var summary = R20.campaignSummary('computedSummary');
            if (!wanted || summary === undefined || summary === null) { return null; }
            if (typeof summary === 'string') {
                summary = Utils.safeJsonParse(summary.trim(), null);
            }
            if (Array.isArray(summary)) {
                for (var index = 0; index < summary.length; index += 1) {
                    var entry = summary[index];
                    var name = typeof entry === 'string' ? entry : (Utils.isObject(entry)
                        ? String(entry.name || entry.property || entry.id || '') : '');
                    if (String(name || '').trim().toLowerCase() === wanted) {
                        return { name: String(name || requested).trim() || requested, metadata: Utils.isObject(entry) ? entry : {} };
                    }
                }
                return null;
            }
            if (!Utils.isObject(summary)) { return null; }
            var keys = Object.keys(summary);
            for (var keyIndex = 0; keyIndex < keys.length; keyIndex += 1) {
                var key = keys[keyIndex];
                if (String(key || '').trim().toLowerCase() === wanted) {
                    return { name: String(key || requested).trim() || requested, metadata: Utils.isObject(summary[key]) ? summary[key] : {} };
                }
            }
            return null;
        }

