            var record = {};
            record.id = cleanId(value.id || key, path + '.id');
            if (Utils.normalizedIdentity(record.id) !== Utils.normalizedIdentity(key)) { invalid(path + '.id', 'must match its collection key.'); }
            record.name = cleanText(value.name || record.id, path + '.name', CONFIG.shop.maximumNameLength, true);
            record.kind = enumValue(value.kind, CONFIG.shop.assetKinds, path + '.kind');
