                                lockedWorldPlan.targetTokenId = Utils.objectId(lockedSource.sourceToken);
                                lockedWorldPlan.targetCharacterId = Utils.objectId(lockedSource.sourceCharacter);
                                lockedWorldPlan.targetName = lockedWorldPlan.objectName || I18N.t('mapInteractions.door');
