            projected.runtime.linkedShopItems = Utils.isObject(projected.runtime.linkedShopItems) ? projected.runtime.linkedShopItems : {};
            projected.runtime.linkedShopItems[shopKey] = Utils.isObject(projected.runtime.linkedShopItems[shopKey])
                ? projected.runtime.linkedShopItems[shopKey] : {};
            var next = Utils.isObject(projected.runtime.linkedShopItems[shopKey][itemKey])
                ? Utils.clone(projected.runtime.linkedShopItems[shopKey][itemKey]) : {};
            var source = Utils.isObject(patch) ? patch : {};
            if (source.remove === true) { next = {}; }
            if (source.remove !== true && source.discountPercent !== undefined) { next.discountPercent = Math.round(Utils.clamp(Utils.toNumber(source.discountPercent, 0), 0, 100) * 100) / 100; }
            if (source.remove !== true && source.origin !== undefined) {
                if (Utils.isNonEmptyString(source.origin)) { next.origin = String(source.origin).slice(0, 40); } else { delete next.origin; }
            }
            if (source.remove !== true && source.restockQuantity !== undefined) {
                var quantity = Number(source.restockQuantity);
                if (Number.isSafeInteger(quantity) && quantity >= 0 && quantity < 999) { next.restockQuantity = quantity; }
                else { delete next.restockQuantity; }
            }
            if (Object.keys(next).length) { projected.runtime.linkedShopItems[shopKey][itemKey] = next; }
            else { delete projected.runtime.linkedShopItems[shopKey][itemKey]; }
            deleteEmptyParent(projected.runtime.linkedShopItems, shopKey);
            if (!StateBudgetService.fitsReplacement('shops', projected)) { return { ok: false, error: 'Linked Shop metadata exceeds the configured state budget.' }; }
            Object.keys(current).forEach(function (key) { delete current[key]; });
