            var projected = normalized(current);
            var next = Math.max(0, Utils.toInt(projected.runtime.rotationNonces[key], 0)) + 1;
            if (!Number.isSafeInteger(next)) { next = 1; }
            projected.runtime.rotationNonces[key] = next;
