            var shopLimits = Utils.isObject(limits[String(shopId || '')]) ? limits[String(shopId || '')] : {};
            var offerLimits = Utils.isObject(shopLimits[String(offerId || '')]) ? shopLimits[String(offerId || '')] : {};
            var canonical = offerLimits[String(characterId || '')];
            if (canonical !== undefined) { return Utils.clone(canonical); }
            var legacyCharacter = Utils.isObject(limits[String(characterId || '')])
                ? limits[String(characterId || '')] : {};
            return legacyCharacter[String(offerId || '')] === undefined
                ? undefined : Utils.clone(legacyCharacter[String(offerId || '')]);
