                                orderQuantity: orderQuantity,
                                walletBefore: walletBefore, walletAfter: debit.wallet,
                                walletBeforeFingerprint: TransactionService.fingerprint(walletBefore),
                                walletAfterFingerprint: TransactionService.fingerprint(debit.wallet),
                                inventoryBefore: current[1], inventoryBeforeFingerprint: TransactionService.fingerprint(current[1]),
