                                    { id: 'inventory-delivery', name: 'Inventory delivery', status: 'pending' },
                                    { id: 'commerce-commit', name: 'Commerce and analytics commit', status: 'pending' },
                                    { id: 'event-publication', name: 'Post-commit event publication', status: 'pending' }
