                type: String(source.type || '').trim().toLowerCase(),
                subtype: String(source.subtype || '').trim().toLowerCase(),
                rarity: String(source.rarity || source.quality || 'common').trim().toLowerCase(),
                price: Utils.clone(PricingService.normalizePrice(source.price)),
                weight: Utils.toNumber(source.weight, 0),
