            var current = read(character);
            if (!current.ok) { return current; }
            if (current.macros.length >= MAX_MACROS) { return { ok: false, error: 'Player macro limit reached.' }; }
            var macro = normalizeMacro({ id: Utils.uniqueId('player-macro'), name: name, action: action });
            if (!macro.name || !macro.action) { return { ok: false, error: 'Macro Name and Function are required.' }; }
