            TemporaryMapDrawingService.drawTokenOutline(tokens[1], { ttlMs: 30000, reason: 'debug-distance-circle', stroke: '#ffbf00', strokeWidth: 3 });
            TemporaryMapDrawingService.drawLine(measurement.pageId, layer, measurement.visuals.centerLine, { ttlMs: 30000, reason: 'debug-distance-center-line', stroke: '#1e88ff', strokeWidth: 5 });
            TemporaryMapDrawingService.drawLine(measurement.pageId, layer, measurement.visuals.circleEdgeLine, { ttlMs: 30000, reason: 'debug-distance-circle-edge-line', stroke: '#ff2222', strokeWidth: 5 });
            TemporaryMapDrawingService.drawLine(measurement.pageId, layer, measurement.visuals.boxEdgeLine, { ttlMs: 30000, reason: 'debug-distance-box-edge-line', stroke: '#ffd400', strokeWidth: 5 });
