            var dawn = CONFIG.world.mapLightDawnSchedule || [];
            var dusk = CONFIG.world.mapLightDuskSchedule || [];
            var dawnStart = dawn.length ? Utils.toInt(dawn[0].minute, 330) : 330;
            var dawnEnd = dawn.length ? Utils.toInt(dawn[dawn.length - 1].minute, 480) : 480;
            var duskStart = dusk.length ? Utils.toInt(dusk[0].minute, 1080) : 1080;
            var duskEnd = dusk.length ? Utils.toInt(dusk[dusk.length - 1].minute, 1230) : 1230;
            if (totalMinutes < dawnStart) { return 0; }
            if (totalMinutes <= dawnEnd) { return scheduledLightPercent(totalMinutes, dawn, 0); }
            if (totalMinutes < duskStart) { return 100; }
            if (totalMinutes <= duskEnd) { return scheduledLightPercent(totalMinutes, dusk, 100); }
            return 0;
