            var allowOccupiedDestination = RuntimeConfig.get('TOKEN_ALLOW_MOVEMENT_INTO_OCCUPIED_SPACES', false) === true;
            var tokensBlockMovement = RuntimeConfig.get('TOKEN_TOKENS_BLOCK_MOVEMENT', false) === true;
