                    searchPaddingCells: RuntimeConfig.get('TOKEN_FOLLOW_SEARCH_PADDING_CELLS', CONFIG.navigation.searchPaddingCells),
                    maximumWaypoints: RuntimeConfig.get('TOKEN_FOLLOW_MAX_WAYPOINTS', CONFIG.navigation.maximumWaypoints),
                    maximumSearchNodes: RuntimeConfig.get('TOKEN_FOLLOW_MAX_SEARCH_NODES', CONFIG.navigation.maximumSearchNodes),
                    maximumOpenHeapEntries: RuntimeConfig.get('TOKEN_FOLLOW_MAX_HEAP_ENTRIES', CONFIG.navigation.maximumOpenHeapEntries),
                    maximumPlanningMs: RuntimeConfig.get('TOKEN_FOLLOW_MAX_PLANNING_MS', CONFIG.navigation.maximumPlanningMs),
                    doorDelayMs: RuntimeConfig.get('TOKEN_FOLLOW_DOOR_DELAY_MS', CONFIG.navigation.followDoorDelayMs),
                    doorHoldSteps: RuntimeConfig.get('TOKEN_FOLLOW_DOOR_HOLD_STEPS', CONFIG.navigation.followDoorHoldSteps),
                    maximumDoorTransitions: RuntimeConfig.get('TOKEN_FOLLOW_MAX_DOOR_TRANSITIONS', CONFIG.navigation.maximumDoorTransitions),
                    source: entry && entry.mode === 'move' ? 'move' : 'follow',
