                    lossInfo.debt = recorded && recorded.debt || null;
                    lossInfo.cleanupWarning = !(removed && removed.ok);
                    if (lossInfo.cleanupWarning) {
                        Logger.warn('Lost rental was closed but one or more token copies could not be removed', {
                            contractId: contract.id, instanceId: instance.instanceId,
                            error: removed && removed.error || I18N.t('inventory.useSpawnCleanupFailed')
                        });
                    }
                    try { ShopCommandController.renderRentalLossNotice(lossInfo); }
                    catch (noticeError) {
                        Logger.warn('Rental loss notification failed', { contractId: contract.id,
                            error: noticeError && noticeError.message || String(noticeError || '') });
                    }
