            var languageCommand = META.dmCommand + ' setting set-language ?{' + I18N.t('dm.language') + '|English,en|Español,es|Custom,custom}';
            var backgroundCommand = META.dmCommand + ' setting set-background ?{Background Image URL|' + CONFIG.card.defaultBodyImageUrl + '}';
