                body: body,
                buildOptions: { bodyAlign: 'left', titleHtml: dmTitleTextHtml(I18N.t('dm.combatAssistantSettingsTitle')),
                    titleBgColor: settingsTitleBackground(GuiTuningService.get('button.dmCombatColor')) }
